if (name === 'credentials' && entry.endsWith('.credential.revoked')) {
  const path = join(directory, entry)
  const stat = lstatSync(path)
  if (!stat.isFile() || stat.isSymbolicLink() || stat.size > 512) throw Error('BACKUP_CREDENTIAL_MARKER_INVALID')
  const marker = z.strictObject({ format: z.literal(1), connectionId: z.uuid(), reason: z.literal('restored-deletion') }).parse(JSON.parse(readFileSync(path, 'utf8')))
  if (entry !== marker.connectionId + '.credential.revoked') throw Error('BACKUP_CREDENTIAL_MARKER_INVALID')
}
files.push(name + '/' + entry)
